insert into public.quiz_questions (id, course_version_id, level, question, options, correct_index, explanation, sort_order)
values ('33333333-3333-3333-3333-100000000000', '22222222-2222-2222-2222-222222222222', 'intro', 'What are the three software safety classes defined in IEC 62304?', '["Class 1, Class 2, Class 3", "Class A, Class B, Class C", "Low, Medium, High", "Minor, Serious, Critical"]'::jsonb, 1, 'IEC 62304 defines Classes A, B and C. Amendment 1 revised §4.3 from a severity-only test to a risk-based one: Class A is software that cannot contribute to a hazardous situation, or that can but where the risk is not unacceptable once risk control measures external to the software are taken into account; Class B is where unacceptable risk remains and the possible harm is non-serious injury; Class C is where unacceptable risk remains and the possible harm is death or serious injury.', 0)
