insert into public.quiz_questions (id, course_version_id, level, question, options, correct_index, explanation, sort_order)
values ('33333333-3333-3333-3333-100000000004', '22222222-2222-2222-2222-222222222222', 'intro', 'Which international standard does IEC 62304 Clause 7 link software risk management to?', '["ISO 13485", "ISO 14971", "IEC 60601-1", "ISO 9001"]'::jsonb, 1, 'Clause 7 integrates with ISO 14971, the risk management standard for medical devices. Software risk control measures must be evaluated within the broader device risk management framework.', 4)
