insert into public.quiz_questions (id, course_version_id, level, question, options, correct_index, explanation, sort_order)
values ('33333333-3333-3333-3333-100000000005', '22222222-2222-2222-2222-222222222222', 'intro', 'What is the primary purpose of software configuration management under Clause 8?', '["To plan software testing activities", "To control and track software items throughout the lifecycle", "To document software risk mitigations", "To define the software release process"]'::jsonb, 1, 'Configuration management ensures all software items and their versions are uniquely identified, controlled, and traceable — critical for reproducibility and regulatory audit trails.', 5)
on conflict (id) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;

insert into public.quiz_questions (id, course_version_id, level, question, options, correct_index, explanation, sort_order)
values ('33333333-3333-3333-3333-100000000006', '22222222-2222-2222-2222-222222222222', 'intro', 'A software system can contribute to a hazardous situation which still results in unacceptable risk after risk controls external to the software have been considered, and the possible harm is death or serious injury. Which safety class applies?', '["Class A", "Class B", "Class C", "There is no Class D"]'::jsonb, 2, 'That is the Class C test in §4.3 as amended, and the wording matters. Under Amendment 1, software that could contribute to a hazardous situation involving death or serious injury is not automatically Class C — if risk control measures external to the software reduce the risk to an acceptable level, it may be Class A. Class A does not simply mean no injury is possible. There is no Class D in IEC 62304.', 6)
on conflict (id) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;

insert into public.quiz_questions (id, course_version_id, level, question, options, correct_index, explanation, sort_order)
values ('33333333-3333-3333-3333-100000000007', '22222222-2222-2222-2222-222222222222', 'intro', 'Which clause covers the software maintenance process in IEC 62304?', '["Clause 5", "Clause 6", "Clause 7", "Clause 9"]'::jsonb, 1, 'Clause 6 covers the Software Maintenance Process, governing how modifications, corrections, and enhancements to released software are planned and controlled.', 7)
on conflict (id) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;

